const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: 8765 });
const nodeReds = [];
const lastNumbers = [];

function sendMessage(client, message) {
    if (client.readyState === WebSocket.OPEN) {
        var delay = random_delay();
    
        setTimeout(() => {
        }, delay);
        client.send(message);
    }
}

function random_delay(){
    let randomNumber = Math.floor(Math.random() * 301);
    while (lastNumbers.some((num) => Math.abs(randomNumber - num) < 30)) {
        randomNumber = Math.floor(Math.random() * 301);
    }
    
    lastNumbers.push(randomNumber);
    if (lastNumbers.length > 5) {
        lastNumbers.shift();
    }
    
    return randomNumber;
}

wss.on('connection', function connection(ws) {
        nodeReds.forEach(nodeRed => {
            nodeRed.status({fill:"green",shape:"dot",text:"connected"});
        });
        ws.on('message', function incoming(message) {
        sendMessage(ws, 'Received: ' + message);
    });

    ws.on('close', function close() {
        nodeReds.forEach(nodeRed => {
            nodeRed.status({fill:"red",shape:"ring",text:"disconnected"});
        });
    });
});

module.exports = function(RED) {
    function IOT_connect(config) {
        RED.nodes.createNode(this, config);

        var node = this;
        // node.status({fill:"red",shape:"ring",text:"disconnected"});
        nodeRed = this;
        nodeReds.push(node);
        
        this.on('input', function(msg, send, done) {
            wss.clients.forEach(function each(client) {
                sendMessage(client, JSON.stringify(msg.payload));
            });
            done();
        });
    }

    RED.nodes.registerType('IOT Send', IOT_connect);
};